package pl.trenerai.web;

import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import pl.trenerai.model.UserSettings; import pl.trenerai.repository.UserSettingsRepository; import pl.trenerai.service.*;
@Controller @RequestMapping("/settings") public class SettingsController { private final CurrentUserService current;private final UserSettingsRepository settings;private final SecretCrypto crypto; public SettingsController(CurrentUserService c,UserSettingsRepository s,SecretCrypto crypto){current=c;settings=s;this.crypto=crypto;} @GetMapping String page(Model model){model.addAttribute("settings",current.settings());return "settings";} @PostMapping String save(@RequestParam String openAiKey,@RequestParam String stravaClientId,@RequestParam String stravaClientSecret){UserSettings set=current.settings();if(!openAiKey.isBlank())set.setOpenAiKeyEncrypted(crypto.encrypt(openAiKey));if(!stravaClientId.isBlank())set.setStravaClientIdEncrypted(crypto.encrypt(stravaClientId));if(!stravaClientSecret.isBlank())set.setStravaClientSecretEncrypted(crypto.encrypt(stravaClientSecret));settings.save(set);return "redirect:/settings?saved";} }
